document.addEventListener('DOMContentLoaded',function (){console.log('Science Gates-Study in Malaysia');initializeFormsets();});function initializeFormsets(){const formsetContainers=document.querySelectorAll('[data-formset]');formsetContainers.forEach(container=>{const formsetPrefix=container.getAttribute('data-formset');const itemName=container.getAttribute('data-item-name')||'Item';new FormsetManager(formsetPrefix,itemName);});}